{
  "schemaVersion": 1,
  "entries": [
    {
      "id": "science-pressure",
      "stages": [
        {
          "id": "observe",
          "goal": "Eine Vorhersage am Modell prüfen.",
          "example": "Im Modell wirken immer 12 N. Vergleiche die Flächen 1 m² und 6 m².",
          "prompt": "Was erwartest du bei der größeren Fläche?",
          "hint": "Unterscheide die gesamte Kraft von der Kraft auf jedem gleich großen Flächenteil.",
          "answers": [
            {
              "id": "reasoned",
              "text": "Der Druck wird kleiner.",
              "feedback": "12 N verteilen sich auf mehr Fläche: 12 Pa bei 1 m², 2 Pa bei 6 m². Die Gesamtkraft bleibt gleich."
            },
            {
              "id": "confusion-a",
              "text": "Die gesamte Kraft wird kleiner.",
              "feedback": "Im Modell bleiben die 12 N eingestellt. Geändert wird die Fläche, nicht die Gesamtkraft."
            },
            {
              "id": "confusion-b",
              "text": "Der Druck wird größer.",
              "feedback": "Mehr Fläche verteilt dieselbe Kraft auf mehr gleich große Teile. Auf jeden Teil entfällt weniger Kraft."
            }
          ],
          "correct": "reasoned"
        },
        {
          "id": "explain",
          "goal": "Das Zusammenspiel zweier Größen erklären.",
          "example": "Ein gedachtes zweites Modell hat doppelt so viel Kraft und doppelt so viel Kontaktfläche.",
          "prompt": "Wie ändert sich der gleichmäßige Druck?",
          "hint": "Druck ist Kraft geteilt durch Fläche. Betrachte beide Änderungen zusammen.",
          "answers": [
            {
              "id": "confusion-a",
              "text": "Er wird doppelt so groß.",
              "feedback": "Das berücksichtigt nur die größere Kraft. Die ebenfalls verdoppelte Fläche verteilt sie wieder auf doppelt so viele Teile."
            },
            {
              "id": "confusion-b",
              "text": "Er wird halb so groß.",
              "feedback": "Das berücksichtigt nur die größere Fläche. Gleichzeitig wirkt aber doppelt so viel Kraft."
            },
            {
              "id": "reasoned",
              "text": "Er bleibt gleich.",
              "feedback": "Zähler und Nenner des Quotienten werden beide verdoppelt. Dadurch bleibt die Kraft je Fläche gleich."
            }
          ],
          "correct": "reasoned"
        },
        {
          "id": "transfer",
          "goal": "Das Prinzip auf einen neuen Fall übertragen.",
          "example": "Zwei gleich schwere gedachte Fahrzeuge stehen auf demselben weichen Boden. Eines verteilt sein Gewicht über größere Kontaktflächen. Wir vergleichen nur den mittleren Druck.",
          "prompt": "Welche begründete Vorhersage passt?",
          "hint": "Trenne die Vorhersage des Druckmodells von einer Garantie über den echten Boden.",
          "answers": [
            {
              "id": "confusion-b",
              "text": "Mit größerer Kontaktfläche kann ein Fahrzeug nie mehr einsinken.",
              "feedback": "Das Modell vergleicht Druck. Es berechnet weder die Tragfähigkeit noch Wassergehalt oder Verformung des Bodens."
            },
            {
              "id": "reasoned",
              "text": "Größere Kontaktflächen verringern den mittleren Druck; Einsinken hängt noch vom Boden ab.",
              "feedback": "Bei gleicher Gewichtskraft sinkt Kraft pro Fläche. Wie ein echter Boden nachgibt, erklärt dieses einfache Druckmodell allein nicht."
            },
            {
              "id": "confusion-a",
              "text": "Größere Kontaktflächen machen das Fahrzeug leichter.",
              "feedback": "Die Masse und damit die Gewichtskraft bleiben im Vergleich gleich. Nur die Verteilung der Kraft ändert sich."
            }
          ],
          "correct": "reasoned"
        }
      ],
      "sources": [
        "https://www1.grc.nasa.gov/beginners-guide-to-aeronautics/air-pressure/"
      ],
      "interactive": true
    },
    {
      "id": "science-buoyancy",
      "stages": [
        {
          "id": "observe",
          "goal": "Eine Modellvorhersage mit einer Beobachtung vergleichen.",
          "example": "Der gedachte starre Körper hat 3 kg Masse und 1 Liter Volumen. Das Wasser hat ungefähr 1 kg Masse je Liter.",
          "prompt": "Was erwartest du im Modell?",
          "hint": "Vergleiche die Körpermasse mit der Wassermasse, die der ganz eingetauchte Körper verdrängen kann.",
          "answers": [
            {
              "id": "confusion-a",
              "text": "Der Körper schwimmt immer, weil Wasser nach oben drückt.",
              "feedback": "Auftrieb wirkt auch auf einen sinkenden Körper. Entscheidend ist, ob er dessen Gewichtskraft ausgleichen kann."
            },
            {
              "id": "confusion-b",
              "text": "Er schwebt, weil der Auftrieb beim Eintauchen immer automatisch die Gewichtskraft ausgleicht.",
              "feedback": "Ein sinkender Körper erfährt Auftrieb, aber nicht automatisch genug für Gleichgewicht. Hier reicht das Gewicht von ungefähr 1 kg verdrängtem Wasser nicht für die Gewichtskraft von 3 kg."
            },
            {
              "id": "reasoned",
              "text": "Der Körper sinkt.",
              "feedback": "Ganz eingetaucht verdrängt er nur ungefähr 1 kg Wasser. Dessen Gewicht reicht hier nicht aus, die Gewichtskraft von 3 kg auszugleichen."
            }
          ],
          "correct": "reasoned"
        },
        {
          "id": "explain",
          "goal": "Tatsächlichen und maximalen Auftrieb unterscheiden.",
          "example": "Derselbe Körper hat nun 4 Liter Volumen und schwimmt in Ruhe. Seine Masse bleibt 3 kg.",
          "prompt": "Wie viel Wasser verdrängt er dabei ungefähr?",
          "hint": "Im ruhigen Schwimmen gleichen sich Auftrieb und Gewichtskraft aus. Nicht das ganze Körpervolumen muss unter Wasser sein.",
          "answers": [
            {
              "id": "confusion-b",
              "text": "1 Liter, weil 4 minus 3 gleich 1 ist.",
              "feedback": "Die Differenz beschreibt hier den nicht eingetauchten Volumenanteil. Für den Auftrieb zählt das tatsächlich verdrängte Wasser."
            },
            {
              "id": "reasoned",
              "text": "3 Liter.",
              "feedback": "3 Liter dieses Wassers haben etwa 3 kg Masse. So ist die Gewichtskraft ausgeglichen; etwa ein Viertel des Körpervolumens bleibt über Wasser."
            },
            {
              "id": "confusion-a",
              "text": "4 Liter, weil sein gesamtes Volumen zählt.",
              "feedback": "4 Liter wäre das verdrängte Volumen bei vollständigem Untertauchen. Der schwimmende Körper taucht hier nur teilweise ein."
            }
          ],
          "correct": "reasoned"
        },
        {
          "id": "transfer",
          "goal": "Eine Vorhersage unter veränderten Bedingungen begründen.",
          "example": "Ein unverändertes schwimmendes Modellboot kommt von Süßwasser in dichteres Salzwasser. Wir betrachten ruhiges Gleichgewicht, keine Wellen oder Stabilität.",
          "prompt": "Welche Änderung passt dazu?",
          "hint": "Gleiche Bootmasse bedeutet gleiche Gewichtskraft. Ein Liter dichterer Flüssigkeit hat mehr Masse.",
          "answers": [
            {
              "id": "reasoned",
              "text": "Das Boot muss weniger Flüssigkeitsvolumen verdrängen.",
              "feedback": "Für denselben Auftrieb ist dieselbe verdrängte Flüssigkeitsmasse nötig. Bei größerer Dichte nimmt diese Masse weniger Volumen ein."
            },
            {
              "id": "confusion-a",
              "text": "Das Boot muss mehr Flüssigkeitsvolumen verdrängen.",
              "feedback": "Das würde bei dichterem Wasser mehr verdrängte Masse und damit mehr Auftrieb bedeuten, obwohl die Gewichtskraft gleich bleibt."
            },
            {
              "id": "confusion-b",
              "text": "Der Auftrieb muss im neuen Gleichgewicht größer als die Gewichtskraft bleiben.",
              "feedback": "Ein dauerhaft größeres Aufwärtsresultat wäre kein ruhiges Gleichgewicht. Beim Schwimmen gleichen sich beide Kräfte aus."
            }
          ],
          "correct": "reasoned"
        }
      ],
      "sources": [
        "https://www.noaa.gov/office-education/outreach-communication/hands-on-science-activities/build-a-boat"
      ],
      "interactive": true
    },
    {
      "id": "science-lever",
      "stages": [
        {
          "id": "observe",
          "goal": "Eine Veränderung am idealen Hebel vorhersagen.",
          "example": "Die Last beträgt 12 N im Abstand 1 m vom Drehpunkt. Vergleiche Kraftarme von 1 m und 2 m.",
          "prompt": "Was erwartest du für die benötigte senkrechte Kraft am längeren Arm?",
          "hint": "Vergleiche das Produkt aus Kraft und Abstand zum Drehpunkt.",
          "answers": [
            {
